function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must be lists of the same length.';
  if (operations[0] !== 'LUPrefix' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with LUPrefix and one argument n.';
  const n = args[0][0];
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is an integer from 1 to 10^5.';
  if (operations.length - 1 > 200000) return 'At most 2 * 10^5 calls to upload and longest.';
  const seen = new Set();
  let asked = false;
  for (let i = 1; i < operations.length; i++) {
    const call = args[i];
    if (operations[i] === 'upload') {
      if (!Array.isArray(call) || call.length !== 1 || !Number.isInteger(call[0]) || call[0] < 1 || call[0] > n) return 'upload takes one video from 1 to n.';
      if (seen.has(call[0])) return 'Each video is uploaded at most once.';
      seen.add(call[0]);
    } else if (operations[i] === 'longest') {
      if (!Array.isArray(call) || call.length !== 0) return 'longest takes no arguments.';
      asked = true;
    } else return 'Only upload and longest can follow the constructor.';
  }
  if (!asked) return 'Call longest at least once.';
  return null;
}

