class LUPrefix {
  // Keep a flag per video and count the prefix from video 1 on every query.
  constructor(n) {
    this.n = n;
    this.done = new Array(n + 2).fill(false);
  }
  upload(video) {
    this.done[video] = true;
  }
  longest() {
    let count = 0;
    while (count < this.n && this.done[count + 1]) count++;
    return count;
  }
}

