function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 200 + pick(100) : 1 + pick(7);
  const order = Array.from({ length: n }, (_, k) => k + 1);
  // Either a full shuffle or a nearly sorted order, so the prefix grows in both big jumps and small steps.
  const swaps = rand() < 0.5 ? n : Math.ceil(n / 10);
  for (let s = 0; s < swaps; s++) {
    const k = pick(n);
    const j = rand() < 0.5 ? pick(n) : Math.min(n - 1, k + pick(4));
    [order[k], order[j]] = [order[j], order[k]];
  }
  const uploads = size === 'large' ? order : order.slice(0, pick(n + 1));
  const operations = ['LUPrefix'];
  const args = [[n]];
  const budget = size === 'large' ? 498 : 12;
  let next = 0;
  while (operations.length - 1 < budget && (next < uploads.length || operations.length - 1 < 2)) {
    if (next < uploads.length && rand() < 0.6) {
      operations.push('upload');
      args.push([uploads[next++]]);
    } else {
      operations.push('longest');
      args.push([]);
    }
  }
  operations.push('longest');
  args.push([]);
  return [operations, args];
}
